class Solution {
    public int countSubmatrices(int[][] grid,int k){
        long[] columnSums=new long[grid[0].length];
        int answer=0;
        for(int[] row:grid){
            long prefix=0;
            for(int column=0;column<row.length;column++){
                columnSums[column]+=row[column];
                prefix+=columnSums[column];
                if(prefix<=k)answer++;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countSubmatrices(grid:Array<IntArray>,k:Int):Int{
        val columnSums=LongArray(grid[0].size)
        var answer=0
        for(row in grid){
            var prefix=0L
            for(column in row.indices){
                columnSums[column]+=row[column]
                prefix+=columnSums[column]
                if(prefix<=k)answer++
            }
        }
        return answer
    }
}

code.cpp:
class Solution {
public:
    int countSubmatrices(vector<vector<int>>& grid,int k){
        vector<long long> columnSums(grid[0].size());
        int answer=0;
        for(auto& row:grid){
            long long prefix=0;
            for(int column=0;column<(int)row.size();++column){
                columnSums[column]+=row[column];
                prefix+=columnSums[column];
                answer+=prefix<=k;
            }
        }
        return answer;
    }
};
